draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw Anne
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 20);
  ctx.lineTo(W/2 - 50, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 30);
  ctx.lineTo(W/2 - 70, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 30);
  ctx.lineTo(W/2 - 30, H/2 + 40);
  ctx.stroke();

  // Draw diary
  ctx.fillStyle = 'black';
  ctx.fillRect(W/2 - 20 + Math.sin(t) * 10, H/2 + 60, 40, 20);

  // Draw hiding hope
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2, 10 + Math.sin(t) * 5, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 10 + Math.sin(t) * 5);
  ctx.lineTo(W/2 + 50, H/2 + 20 + Math.sin(t) * 5);
  ctx.stroke();

  ctx.restore();
}
